INSERT INTO settings ("key","value") VALUES ('contacts','{"max": "https://max.ru/u/f9LHodD0cOLbhyaAq7otztBIIIdXwDbKppEWDhWbgAYw_b8hOY71Qcw14Sg", "email": "unosound@yandex.ru", "hours": "Пн–Пт, 10:00 — 18:00. Сб-Вс - по запросам", "phone": "+7 911 963-96-71", "address": "Санкт-Петербург", "telegram": "https://t.me/Alekgorn", "whatsapp": ""}'::jsonb);
INSERT INTO settings ("key","value") VALUES ('faq','[{"a": "Мы интернет-магазин из Санкт-Петербурга и сознательно работаем без розничной точки: аренда зала и зарплата продавцов не заложены в цену, поэтому у нас дешевле. Заказ привезём курьером по городу или отправим СДЭК по России — в обоих случаях платите при получении, ничего не переводя заранее. Можно забрать и в пункте выдачи Ozon, Wildberries или Яндекс.Маркета рядом с домом.", "q": "Почему нет магазина, где можно посмотреть товар?"}, {"a": "В пункт выдачи Ozon, WB или Яндекс.Маркета — бесплатно от 3 000 ₽. Курьером по Санкт-Петербургу и через СДЭК по России — бесплатно от 6 000 ₽, с оплатой при получении. Заказ меньше — доставка от 500 ₽, точную сумму назовём при подтверждении, когда будет известен город и способ. Неожиданных сумм в конце не будет.", "q": "Сколько стоит доставка?"}, {"a": "Пришлите фото панели в мессенджер — подберём под вашу марку, модель и год, это надёжнее, чем смотреть коробку в магазине. Если всё же не подошло: товар без следов монтажа принимаем обратно 14 дней. Ошиблись мы в подборе — обмен и доставку берём на себя.", "q": "А вдруг товар не подойдёт к моей машине?"}, {"a": "Останется. Штатную проводку не режем: подключение идёт через переходной жгут в заводскую фишку и CAN-адаптер. Всё обратимо — при желании возвращается к стоку за полчаса.", "q": "Что будет с заводской гарантией на автомобиль?"}, {"a": "Оставьте заявку с маркой, моделью и годом. Часть позиций мы возим под заказ: срок 3–10 дней. Если под вашу машину заводского решения нет, честно скажем об этом, а не предложим «универсальное».", "q": "В каталоге нет моей модели — что делать?"}, {"a": "От 1 года на расходные материалы до 2 лет на магнитолы, камеры и регистраторы. Срок указан в карточке каждой позиции.", "q": "Какая гарантия на само оборудование?"}, {"a": "Да, большинство позиций ставятся без пайки. В комплекте идут переходной жгут, рамка и схема подключения по цветам — остаётся снять панель и состыковать разъёмы.", "q": "Можно поставить самому?"}, {"a": "Да, если в комплекте или отдельно взят CAN-адаптер под вашу модель. Он же передаёт скорость, заднюю передачу и данные штатных парктроников на магнитолу.", "q": "Сохранятся ли кнопки на руле?"}, {"a": "Товар без следов монтажа принимаем обратно в течение 14 дней. Если позиция не подошла по нашей ошибке в подборе — обмен и доставку берём на себя.", "q": "Как оформить возврат?"}, {"a": "Да. Для сервисов и частных установщиков есть оптовые цены, расходка со склада, схемы подключения по моделям и документы для юрлица. Напишите — пришлём прайс.", "q": "Работаете с установщиками и СТО?"}]'::jsonb);
