INSERT INTO settings ("key","value") VALUES ('scenarios','[{"cta": "Собрать комплект", "icon": "MonitorSmartphone", "slug": "ekran-nedorogo", "text": "Соберём комплект на вашу машину — всё подойдёт друг к другу.", "title": "Магнитола с рамкой и проводкой"}, {"cta": "Подобрать по авто", "icon": "Cable", "slug": "registrator", "text": "1300 рамок и 400 жгутов. Скажите марку — покажем, что встанет без доработки.", "title": "Рамка и проводка на мою машину"}, {"cta": "Посмотреть решения", "icon": "ParkingCircle", "slug": "parkovka", "text": "Камеры заднего вида, парктроники, регистраторы. Подходят к любой машине.", "title": "Видеть всё вокруг"}, {"cta": "Смотреть всё", "icon": "LayoutGrid", "slug": "vse-po-mashine", "text": "Весь каталог, отфильтрованный под ваш автомобиль.", "title": "Всё для моей машины"}, {"slug": "ekran-premium", "hidden": true}, {"slug": "obzor-360", "hidden": true}, {"slug": "remont-provodki", "hidden": true}, {"slug": "shumoizolyaciya", "hidden": true}]'::jsonb);
INSERT INTO settings ("key","value") VALUES ('product_levels','[{"id": "base", "extra": [], "specs": [["Процессор", "4 ядра, 1.3–1.5 ГГц"], ["Память", "2/32 или 4/64 ГБ"], ["Экран", "IPS, 1280×800"], ["Возможности", "CarPlay и Android Auto, Wi-Fi, Bluetooth"], ["Звук", "Базовый, без отдельной настройки"]], "suits": "Город и короткие поездки", "title": "Базовый уровень", "active": true, "series": "T100, T133, TS7", "summary": "Замена штатной магнитолы без переплаты: музыка, навигация, камера заднего вида."}, {"id": "mid", "extra": [], "specs": [["Процессор", "8 ядер, 1.6 ГГц"], ["Память", "4/64 или 6/128 ГБ"], ["Экран", "QLED, 1280×800"], ["Возможности", "Отдельный звуковой процессор, усилитель 4×50 Вт"], ["Звук", "16-полосная настройка"]], "suits": "Ежедневные поездки, навигация каждый день", "title": "Средний класс", "active": true, "series": "TS18", "summary": "Спокойно тянет несколько приложений сразу и не устаёт от тяжёлых карт."}, {"id": "pro", "extra": [], "specs": [["Процессор", "8 ядер A75, 2.2–2.7 ГГц"], ["Память", "от 6/128 до 8/256 ГБ"], ["Экран", "IPS или QLED, 2K"], ["Возможности", "Оптический и коаксиальный выход на усилитель"], ["Звук", "Настройка под салон, поканальное подключение"]], "suits": "Дальние поездки, много программ, хороший звук", "title": "Продвинутый", "active": true, "series": "TS105, G85", "summary": "Заметно быстрее отзывается и берётся с запасом на годы вперёд."}, {"id": "top", "extra": [], "specs": [["Процессор", "8 ядер A76, 2.7 ГГц"], ["Память", "8/128 или 8/256 ГБ"], ["Экран", "QLED 2K, до 13,6 дюйма"], ["Возможности", "Поворотный экран у отдельных моделей"], ["Звук", "Максимальная детализация, запас по громкости"]], "suits": "Когда нужен лучший звук и большой экран", "title": "Флагман", "active": true, "series": "TS20, TS10S", "summary": "Максимум, что бывает в андроид-магнитолах: самый быстрый процессор и крупный экран."}]'::jsonb);
INSERT INTO settings ("key","value") VALUES ('showcase','[{"ids": ["android-magnitola-mofond-ts18-9-4-64-gb-qled-carplay", "perehodnaya-ramka-lada-vesta-ng-2022-9-dyuymov-chernaya", "perehodnik-iso-16-pin-android-magnitoly"], "href": "https://xn--80a0adnb7a.xn--p1ai/sborka?p=android-magnitola-mofond-ts18-9-4-64-gb-qled-carplay%2Cperehodnaya-ramka-lada-vesta-ng-2022-9-dyuymov-chernaya%2Cperehodnik-iso-16-pin-android-magnitoly", "note": "Авто со штатной камерой", "term": "2 дня", "image": "", "title": "Lada (ВАЗ) Vesta 2025", "kitName": "Магнитола на "}, {"ids": ["android-magnitola-topway-ts105-9-4-64-gb-ips-2k", "perehodnaya-ramka-honda-civic-2006-2011-9-dyuymov-levyy-rul", "perehodnik-android-magnitoly-honda-civic-2006-2011-hetchbek", "dvuhkamernyy-registrator-ekranom-3-2-1080p"], "href": "https://xn--80a0adnb7a.xn--p1ai/sborka?p=android-magnitola-topway-ts105-9-4-64-gb-ips-2k%2Cperehodnaya-ramka-honda-civic-2006-2011-9-dyuymov-levyy-rul%2Cperehodnik-android-magnitoly-honda-civic-2006-2011-hetchbek%2Cdvuhkamernyy-registrator-ekranom-3-2-1080p", "note": "С сохранением управления климат контролем", "term": "3 дня", "title": "Honda Civic 2007", "kitName": "Магнитола с регистратором на "}, {"ids": ["android-magnitola-fyt-7862s-9-4-64-gb-qled-2k", "perehodnaya-ramka-toyota-fj-cruiser-2006-9-dyuymov-chernaya", "perehodnik-android-magnitoly-toyota-1989-2022", "kamera-zadnego-1080p-25fps-povorotnymi-liniyami-kreplenie"], "href": "https://xn--80a0adnb7a.xn--p1ai/sborka?p=android-magnitola-fyt-7862s-9-4-64-gb-qled-2k%2Cperehodnaya-ramka-toyota-fj-cruiser-2006-9-dyuymov-chernaya%2Cperehodnik-android-magnitoly-toyota-1989-2022%2Ckamera-zadnego-1080p-25fps-povorotnymi-liniyami-kreplenie", "term": "1 день", "title": "Toyota FJ Cruiser 2013", "kitName": "Магнитола на "}, {"ids": ["perehodnaya-ramka-kia-rio-2011-2017-9-dyuymov", "perehodnik-android-magnitoly-hyundai-kia-2009"], "href": "https://xn--80a0adnb7a.xn--p1ai/sborka?p=perehodnaya-ramka-kia-rio-2011-2017-9-dyuymov%2Cperehodnik-android-magnitoly-hyundai-kia-2009", "term": "1 день", "title": "Kia Rio 2012", "kitName": "Рамка с проводкой для магнитолы"}]'::jsonb);
